// A single hub goroutine owns the client set — no locks needed.
func (h *hub) run() {
	for {
		select {
		case c := <-h.register:
			h.clients[c] = true
		case c := <-h.unregister:
			if _, ok := h.clients[c]; ok {
				delete(h.clients, c)
				close(c.send) // signals writePump to exit
			}
		case msg := <-h.broadcast:
			for c := range h.clients {
				select {
				case c.send <- msg:
				default: // slow client: drop it, don't block the hub
					close(c.send)
					delete(h.clients, c)
				}
			}
		}
	}
}
